questionvariables.text:
/* 1. Randomize the radius OA */
r: 5 + rand(11);

/* 2. Exact Mathematical Calculations */
area_tri_exact: (1/2) * r^2 * sin(%pi/4);
ta_exact: 8 * area_tri_exact;

/* 3. Floating Point Evaluation for PRT */
ta_float: float(ta_exact);

/* 4. Display Variables using dispdp to guarantee clean 2-decimal output without fractions */
disp_tri: dispdp(float(area_tri_exact), 4);
disp_ta: dispdp(ta_float, 2);

/* Common Mistakes for PRT */
m1: float(8 * r^2 * sin(%pi/4));      /* Forgot 1/2 */
m2: float(area_tri_exact);            /* Forgot x8 */
m3: float(8 * (1/2) * r * r);         /* Forgot sin(45) */
